using UnityEngine;
public sealed class HeadAccessoryApplier : MonoBehaviour { [SerializeField] private Transform anchor; private GameObject instance; public void SetAccessory(HeadAccessoryDefinition accessory) { if (instance != null) Destroy(instance); if (accessory == null || accessory.Prefab == null || anchor == null) return; instance = Instantiate(accessory.Prefab, anchor); instance.transform.SetLocalPositionAndRotation(accessory.LocalPosition, Quaternion.Euler(accessory.LocalEulerAngles)); instance.transform.localScale = accessory.LocalScale; foreach (AccessoryMaterialColor slot in accessory.MaterialColors) { Transform target = string.IsNullOrEmpty(slot.RendererPath) ? instance.transform : instance.transform.Find(slot.RendererPath); Renderer renderer = target != null ? target.GetComponent<Renderer>() : null; if (renderer == null || slot.MaterialIndex < 0 || slot.MaterialIndex >= renderer.sharedMaterials.Length) continue; Material material = renderer.sharedMaterials[slot.MaterialIndex]; MaterialPropertyBlock block = new(); renderer.GetPropertyBlock(block, slot.MaterialIndex); if (material != null && material.HasProperty("_BaseColor")) block.SetColor("_BaseColor", slot.Color); else if (material != null && material.HasProperty("_Color")) block.SetColor("_Color", slot.Color); renderer.SetPropertyBlock(block, slot.MaterialIndex); } } }
